function syntheticTextlessPdf(){const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << >> /Contents 4 0 R >>','<< /Length 0 >>\nstream\n\nendstream'];let body='%PDF-1.4\n';const offsets=[0];for(let index=0;index<objects.length;index++){offsets.push(Buffer.byteLength(body));body+=`${index+1} 0 obj\n${objects[index]}\nendobj\n`;}const xrefOffset=Buffer.byteLength(body),xref=['xref','0 5','0000000000 65535 f ',...offsets.slice(1).map(offset=>`${String(offset).padStart(10,'0')} 00000 n `)].join('\n');return Buffer.from(`${body}${xref}\ntrailer << /Size 5 /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`);}

