    const stalePageReviews=structuredClone(pageReviews);stalePageReviews[0].rendered_page_sha256='c'.repeat(64);result=await post({...baseReview,category:'visual',decision:'approve',reviewed_ids:['S01','S02'],page_reviews:stalePageReviews});assert.equal(result.status,400);assert.match((await result.json()).error,/current rendered page image/);
